import os,subprocess
from playwright.sync_api import sync_playwright,expect
server=subprocess.Popen(['node','scripts/serve.mjs'],env={**os.environ,'PORT':'14342'},stdout=subprocess.DEVNULL)
try:
 with sync_playwright() as p:
  browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']);errors=[]
  for template in ['platformer','runner3d']:
   for phone in [False,True]:
    c=browser.new_context(viewport={'width':390,'height':844} if phone else {'width':1440,'height':960},is_mobile=phone,has_touch=phone);page=c.new_page();page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:14342');page.evaluate('''async t=>{const{createProject}=await import('/project.js');localStorage.setItem('playform.projects',JSON.stringify([createProject('Simple navigation',t)]))}''',template);page.reload();page.locator('.project-open').click();expect(page.locator('.simple-navigation')).to_be_visible(timeout=12000);expect(page.locator('.simple-editor')).to_be_visible();page.locator('button[data-stage="Add"]').click();add=page.locator('.simple-sidebar [data-add="coin"]');expect(add).to_be_visible();before=page.evaluate('JSON.parse(localStorage.getItem("playform.projects"))[0].objects.length');add.click();assert page.evaluate('JSON.parse(localStorage.getItem("playform.projects"))[0].objects.length')==before+1;page.locator('button[data-stage="Properties"]').click();expect(page.locator('.simple-sidebar input[data-field="name"]' if template=='runner3d' else '.simple-sidebar input[data-prop="name"]')).to_be_visible();page.locator('button[data-stage="Events"]').click();expect(page.locator('.simple-sidebar .three-events' if template=='runner3d' else '.simple-sidebar #panel-workspace')).to_be_visible();page.locator('button[data-stage="Scene"]').click();page.screenshot(path=f'screenshots/simple-{template}-{phone}.png');page.locator('#navigation-play').click();expect(page.locator('#navigation-play')).to_have_text('■ Stop');expect(page.locator('.simple-sidebar')).to_be_hidden();page.wait_for_timeout(300);page.keyboard.press('Space');expect(page.locator('#navigation-play')).to_have_text('■ Stop');page.locator('#navigation-play').click();expect(page.locator('#navigation-play')).to_have_text('▶ Play');page.locator('.simple-menu summary').nth(2).click();page.locator('#navigation-mode').click();expect(page.locator('.simple-editor')).to_have_count(0);expect(page.locator('.three-toolbar' if template=='runner3d' else '.mobile-menu' if phone else '.editor-commandbar').first).to_be_visible();page.locator('#navigation-mode').click();expect(page.locator('.simple-editor')).to_be_visible();page.locator('.simple-menu summary').nth(1).click();page.locator('[data-nav-action="ui"]' if template=='runner3d' else '[data-nav-action="game-ui"]').click();expect(page.locator('.ui-builder')).to_be_visible();page.locator('#ui-cancel').click();assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.reload();page.locator('.project-open').click();expect(page.locator('.simple-editor')).to_be_visible(timeout=10000);c.close();print('PASS',template,'phone' if phone else 'desktop','sections, add/edit/events, play, advanced switch, UI menu and persistence',flush=True)
  assert not errors,errors;browser.close()
finally:server.terminate();server.wait()
